  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const r = parseLine(lines[n], root, cur, curPath)
      if (r) { cur = r.table; curPath = r.path }
    } catch (e) {
      if (e.isConfigError) e.line = n + 1
      throw e
    }
  }
  return root
}

function descend(table, names, prefix, mkHeader) {
  // walks all names but the last; returns the table holding the last name
  let t = table
  for (let i = 0; i < names.length - 1; i++) {
    const nm = names[i]
    let c = t.m.get(nm)
    if (!c) { c = newTable(); t.m.set(nm, c) } else if (c.t === 'array' && c.aot) c = c.items[c.items.length - 1]
    else if (c.t !== 'table') fail(`${[...prefix, ...names.slice(0, i + 1)].join('.')} is not a table`)
    t = c
  }
  return t
}

