      if (i >= line.length) fail('unterminated string')
      const c = line[i++]
      if (c === '"') return s
      if (c !== '\\') { s += c; continue }
      if (i >= line.length) fail('unterminated string')
      const e = line[i++]
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (e in map) s += map[e]
