      let el = newTable()
      if (!ex) t.m.set(last, { t: 'array', items: [el], aot: true })
      else if (ex.t === 'array' && ex.aot) ex.items.push(el)
      else fail(`${path} is not an array of tables`)
      return { table: el, path: names }
    }
